/* ============================================================
 * Verify sitemap URL integrity
 * ------------------------------------------------------------
 * Runs as part of the build. Reads public/sitemap.xml and checks
 * every <loc> against the sources of truth:
 *
 *   1. Every URL must be generated by one of:
 *        - staticRoutes (in this script's sibling)
 *        - tools[] from src/data/tools.ts
 *        - blogPosts[] from src/data/blog.ts
 *        - authors[] from src/data/authors.ts
 *   2. Every URL must have a matching entry in SSR_CONTENT (so
 *      the middleware will serve real HTML, not a 404).
 *   3. Every URL must NOT contain a query string or /edit/ path.
 *
 * If any check fails the build stops with a specific error.
 *
 * Note: does not perform live HTTP requests. The verification is
 * against the same data that produced the sitemap, which is what
 * we actually control.
 * ============================================================ */

import { readFileSync, existsSync } from "node:fs";
import { resolve } from "node:path";
import { tools } from "../src/data/tools";
import { blogPosts } from "../src/data/blog";
import { authors } from "../src/data/authors";

const SITEMAP = resolve(process.cwd(), "public/sitemap.xml");
const SSR_FILE = resolve(process.cwd(), "functions/_ssr-content.ts");

if (!existsSync(SITEMAP)) {
  console.error("❌ public/sitemap.xml does not exist — run 'npm run sitemap'");
  process.exit(1);
}

const xml = readFileSync(SITEMAP, "utf-8");
const locs = [...xml.matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => m[1]);

// Expected URLs from source data
const expected = new Set<string>();
const SITE = "https://ahadex.fun";

// Static routes (must match generate-sitemap.ts staticRoutes)
const staticPaths = [
  "/", "/tools", "/blog", "/about", "/contact",
  "/privacy", "/terms", "/disclaimer", "/accessibility",
  "/cookie-policy", "/editorial-policy", "/affiliate-disclosure",
  "/sitemap",
];
for (const p of staticPaths) expected.add(`${SITE}${p}`);

// Tools
for (const t of tools) expected.add(`${SITE}${t.path}`);

// Blog posts
for (const p of blogPosts) expected.add(`${SITE}/blog/${p.slug}`);

// Authors
for (const a of Object.values(authors)) {
  expected.add(`${SITE}/about/author/${a.id}`);
}

// Check every sitemap URL is expected
const issues: string[] = [];

for (const loc of locs) {
  if (!expected.has(loc)) {
    issues.push(`  • ${loc} — not in any source-of-truth list`);
  }
  if (loc.includes("?") && !loc.includes("sitemap.xml")) {
    issues.push(`  • ${loc} — contains query string`);
  }
  if (loc.includes("/edit/")) {
    issues.push(`  • ${loc} — editor route must not be in sitemap`);
  }
}

// Check SSR coverage for critical paths
const ssrContent = existsSync(SSR_FILE) ? readFileSync(SSR_FILE, "utf-8") : "";

for (const loc of locs) {
  if (loc.includes("sitemap.xml") || loc.includes("rss.xml")) continue;
  const path = loc.replace(SITE, "");
  // Normalize: sitemap generator uses "/path" for tools/blog/author
  if (path === "" || path === "/") {
    if (!ssrContent.includes('"/":')) {
      issues.push(`  • ${loc} — no SSR content for "/"`);
    }
    continue;
  }
  if (!ssrContent.includes(`"${path}":`)) {
    issues.push(`  • ${loc} — no SSR content for path ${path}`);
  }
}

if (issues.length > 0) {
  console.error("");
  console.error("❌ Sitemap verification FAILED:");
  console.error(issues.join("\n"));
  console.error("");
  console.error(`Sitemap URLs: ${locs.length}, expected: ${expected.size}`);
  console.error("");
  process.exit(1);
}

console.log(
  `✅ Sitemap verified — ${locs.length} URLs, all match source data and have SSR content`
);
